/* Cross-runtime golden check: compares site/engine.js output against
 * fixtures generated by the Python engine. Invoked by the Python test suite
 * (and CI) as:  node site/golden_check.mjs <fixtures.json>
 * Exits nonzero, listing every mismatch, if the two engines disagree beyond
 * 1e-9 relative tolerance or any fmtSig string differs.
 */
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { createRequire } from "node:module";

const here = dirname(fileURLToPath(import.meta.url));
createRequire(import.meta.url)(join(here, "engine.js"));
const MF = globalThis.MFEngine;

const fixturePath = process.argv[2];
if (!fixturePath) {
  console.error("usage: node golden_check.mjs <fixtures.json>");
  process.exit(2);
}
const fx = JSON.parse(readFileSync(fixturePath, "utf8"));
const C = JSON.parse(readFileSync(join(here, "..", "modelfootprint", "coefficients.json"), "utf8"));

let failures = 0;
const close = (a, b) => {
  const scale = Math.max(Math.abs(a), Math.abs(b), 1e-30);
  return Math.abs(a - b) / scale < 1e-9;
};

for (const c of fx.compute) {
  const got = MF.compute(C, c.tier, c.tokens, c.region);
  for (const key of ["energy", "water", "carbon"]) {
    for (let i = 0; i < 3; i++) {
      if (!close(got[key][i], c.expected[key][i])) {
        failures++;
        console.error(
          `MISMATCH ${c.tier}/${c.region} ${key}[${i}]: js=${got[key][i]} py=${c.expected[key][i]}`
        );
      }
    }
  }
}

for (const f of fx.fmt_sig) {
  const got = MF.fmtSig(f.x, f.n);
  if (got !== f.expected) {
    failures++;
    console.error(`MISMATCH fmtSig(${f.x}, ${f.n}): js="${got}" py="${f.expected}"`);
  }
}

for (const d of fx.diesel || []) {
  const got = MF.dieselScenario(d.energy, C);
  for (let i = 0; i < 3; i++) {
    if (!close(got.carbon[i], d.expected[i])) {
      failures++;
      console.error(
        `MISMATCH diesel carbon[${i}]: js=${got.carbon[i]} py=${d.expected[i]}`
      );
    }
  }
}

if (failures) {
  console.error(`golden check FAILED: ${failures} mismatch(es)`);
  process.exit(1);
}
console.log(`golden check passed: ${fx.compute.length} compute fixtures, ${fx.fmt_sig.length} fmt_sig fixtures`);
